package posit

import spinal.core._

/** Leading-zero counter, a balanced tree generated by Scala recursion.
  * Returns x.getWidth for an all-zero input; result width is log2Up(width + 1).
  */
object Lzc {
  def apply(x: Bits): UInt = {
    // A sentinel '1' (then zeros) pads x to a power of two, so the tree never sees all zeros.
    val padded = (x ## True).resizeLeft(1 << log2Up(x.getWidth + 1))
    tree(padded)._2
  }

  /** (some bit set, leading zeros) for a power-of-two width. */
  private def tree(x: Bits): (Bool, UInt) =
    if (x.getWidth == 2) (x.orR, (!x(1)).asUInt)
    else {
      val half     = x.getWidth / 2
      val (vh, ch) = tree(x(x.high downto half))
      val (vl, cl) = tree(x(half - 1 downto 0))
      (vh || vl, Mux(vh, U"0" @@ ch, U"1" @@ cl))
    }
}
